L[", %d placed"] = ", %d gesetzt"
L["Each class keeps its own plan on this character. Apply only ever touches your own."] = "Jede Klasse behält ihren eigenen Plan auf diesem Charakter. Setzen berührt immer nur Eure eigene."
L["%s plan open. Your %s plan is kept."] = "%s-Plan geöffnet. Euer %s-Plan bleibt erhalten."
L["Plan another class"] = "Eine andere Klasse planen"
L["Class"] = "Klasse"
L["Opens the classes right here. "] = "Öffnet die Klassen gleich hier. "
L["%d points planned on this character."] = "%d Punkte auf diesem Charakter geplant."
L["No plan yet."] = "Noch kein Plan."
L["Plans"] = "Pläne"
L["Your plans for this class"] = "Eure Pläne für diese Klasse"
L["Keep more than one plan on this character, like the game's equipment sets: one for leveling, one for later. Click to switch, or to make, copy or rename one. Apply follows the open plan."] = "Behaltet mehr als einen Plan auf diesem Charakter, wie die Ausrüstungssets des Spiels: einen zum Leveln, einen für später. Klickt, um zu wechseln oder einen anzulegen, zu kopieren oder umzubenennen. Setzen folgt dem offenen Plan."
L["LEFT"] = "ÜBRIG"
L["PLACED"] = "GESETZT"
L["POINTS"] = "PUNKTE"
L["LEVEL"] = "STUFE"
L["Find a talent"] = "Talent suchen"
L["Spellbook"] = "Zauberbuch"
L["Your spellbook, by level"] = "Euer Zauberbuch, nach Stufe"
L["Every ability of the class from 1 to 60, the level each rank comes, what you have and what is still to come. The game's own book only shows what you have."] = "Jede Fähigkeit der Klasse von 1 bis 60, die Stufe, auf der jeder Rang kommt, was Ihr habt und was noch kommt. Das Buch des Spiels zeigt nur, was Ihr habt."
L["Type part of a name, or of a spell: 'frostbolt' lights every talent that changes Frostbolt. Enter jumps to the first. Escape clears."] = "Tippt einen Teil eines Namens oder eines Zaubers: 'frostblitz' hebt jedes Talent hervor, das Frostblitz verändert. Eingabe springt zum ersten. Esc leert das Feld."
L["The trees show your build as it stands at this level. Roll the wheel here, press the arrows, or click a mark on the path below. Nothing is lost: later points wait their turn. Click the number to jump between your level and 60."] = "Die Bäume zeigen Eure Skillung, wie sie auf dieser Stufe steht. Dreht hier am Mausrad, drückt die Pfeile oder klickt eine Marke auf dem Pfad unten. Nichts geht verloren: Spätere Punkte warten, bis sie dran sind. Klickt die Zahl, um zwischen Eurer Stufe und 60 zu springen."
L["The level you are looking at"] = "Die Stufe, die Ihr anseht"
L["One level earlier"] = "Eine Stufe früher"
L["The trees show the build as it stands at that level. The wheel here does the same."] = "Die Bäume zeigen die Skillung, wie sie auf dieser Stufe steht. Das Mausrad hier tut dasselbe."
L["One level later"] = "Eine Stufe später"
L["Delete this plan"] = "Diesen Plan löschen"
L["Only a plan that is not open can go. Open another first to delete the open one."] = "Nur ein Plan, der nicht offen ist, kann weg. Öffnet erst einen anderen, um den offenen zu löschen."
L["Name a plan"] = "Plan benennen"
L["New"] = "Neu"
L["%s is open and empty. Click a talent, or load a build into it. The chip after your class switches plans."] = "%s ist offen und leer. Klickt ein Talent an oder ladet eine Skillung hinein. Der Chip nach Eurer Klasse wechselt die Pläne."
L["Copy"] = "Kopieren"
L["%s is open, a copy of %s. Change it as you like; %s is kept as it was."] = "%s ist offen, eine Kopie von %s. Ändert sie nach Belieben; %s bleibt, wie er war."
L["Rename"] = "Umbenennen"
L["Type the new name in the box first."] = "Tippt erst den neuen Namen in das Feld."
L["A new, empty plan"] = "Ein neuer, leerer Plan"
L["Opens a fresh plan for this class and keeps the open one. Name it in the box first, or it gets a number."] = "Öffnet einen frischen Plan für diese Klasse und behält den offenen. Benennt ihn vorher im Feld, sonst bekommt er eine Nummer."
L["This plan again"] = "Diesen Plan noch einmal"
L["Opens a copy of the open plan so you can try changes without touching it. Name it in the box first, or it gets a number."] = "Öffnet eine Kopie des offenen Plans, damit Ihr Änderungen probieren könnt, ohne ihn anzurühren. Benennt sie vorher im Feld, sonst bekommt sie eine Nummer."
L["Rename the open plan"] = "Den offenen Plan umbenennen"
L["Type a name in the box, then press this. Enter does the same."] = "Tippt einen Namen in das Feld und drückt dann hier. Eingabe tut dasselbe."
L["YOUR %s PLANS ON THIS CHARACTER"] = "EURE %s-PLÄNE AUF DIESEM CHARAKTER"
L["%s is on your trees."] = "%s ist auf Euren Bäumen."
L["%s deleted."] = "%s gelöscht."
L["The open plan. Apply and the level-up card follow it."] = "Der offene Plan. Setzen und die Stufenkarte folgen ihm."
L["Click to put it on your trees. The open plan waits here for you, as it is."] = "Klickt, um ihn auf Eure Bäume zu legen. Der offene Plan wartet hier auf Euch, so wie er ist."
L["Show all"] = "Alles zeigen"
L["Back to the whole plan"] = "Zurück zum ganzen Plan"
L["Looks at your build at level 60 again, with every planned point on the trees."] = "Zeigt Eure Skillung wieder auf Stufe 60, mit jedem geplanten Punkt auf den Bäumen."
L["Apply next point"] = "Nächsten Punkt setzen"
L["Places the next point of your plan on your character. Until you press this, nothing on your character changes."] = "Setzt den nächsten Punkt Eures Plans auf Eurem Charakter. Bis Ihr hier drückt, ändert sich nichts an Eurem Charakter."
L["Apply all"] = "Alle setzen"
L["Place every point the plan can"] = "Jeden Punkt setzen, den der Plan kann"
L["Goes down your leveling plan and places each unspent point in order. After a reset at the trainer this rebuilds the whole build in one click."] = "Geht Euren Levelplan durch und setzt jeden freien Punkt der Reihe nach. Nach einem Zurücksetzen beim Lehrer baut das die ganze Skillung mit einem Klick wieder auf."
L["From character"] = "Vom Charakter"
L["Your talents as the game has them, now in the plan."] = "Eure Talente, wie das Spiel sie hat, jetzt im Plan."
L["Reset"] = "Zurücksetzen"
L["The plan is already empty."] = "Der Plan ist schon leer."
L["Plan cleared. Your character is untouched."] = "Plan geleert. Euer Charakter ist unberührt."
L["Nothing to undo. Undo brings the plan back after Reset, Load, From character or Keep it."] = "Nichts rückgängig zu machen. Rückgängig bringt den Plan nach Zurücksetzen, Laden, Vom Charakter oder Übernehmen zurück."
L["The plan before is back."] = "Der Plan von vorher ist zurück."
L["Clear"] = "Aufräumen"
L["Load it"] = "Übernehmen"
L["it"] = "Skillung"
L["Import"] = "Importieren"
L["Reminders, hands-free options, the look, sounds, window size, which pages show."] = "Erinnerungen, Automatik, das Aussehen, Töne, Fenstergröße, welche Seiten erscheinen."
L["A bug, a wish, a talent that reads wrong: it goes to the inbox of the person who builds this. Nothing leaves the game by itself; the note becomes a link you paste in a browser."] = "Ein Fehler, ein Wunsch, ein Talent, das falsch dasteht: Es geht in den Posteingang der Person, die das hier baut. Nichts verlässt das Spiel von selbst; die Notiz wird zu einem Link, den Ihr in einen Browser einfügt."
L["This planner is the in-game half of the site. Click for your build's link and a code your phone can read: the same build opens there, on any device. The game does not let an addon open a browser, so the link is copied, not clicked."] = "Dieser Planer ist die Hälfte der Website im Spiel. Klickt für den Link Eurer Skillung und einen Code, den Euer Handy lesen kann: Dieselbe Skillung öffnet sich dort, auf jedem Gerät. Das Spiel lässt ein Addon keinen Browser öffnen, darum wird der Link kopiert, nicht geklickt."
L["Empty the plan"] = "Den Plan leeren"
L["Every point comes back. Nothing happens to your character, and Undo brings the plan back."] = "Jeder Punkt kommt zurück. Eurem Charakter passiert nichts, und Rückgängig bringt den Plan zurück."
L["Brings the plan back from before the last Reset, Load, From character or Keep it. Lit when there is something to bring back."] = "Bringt den Plan von vor dem letzten Zurücksetzen, Laden, Vom Charakter oder Übernehmen zurück. Leuchtet, wenn es etwas zurückzubringen gibt."
L["Back to a quiet window"] = "Zurück zu einem ruhigen Fenster"
L["Takes a tried build's rings off, shows the whole plan again, closes the trainer or spellbook list, empties the search and goes to Home. Your plan and your character stay as they are."] = "Nimmt die Ringe einer probierten Skillung weg, zeigt wieder den ganzen Plan, schließt die Lehrer- oder Zauberbuchliste, leert die Suche und geht zu Start. Euer Plan und Euer Charakter bleiben, wie sie sind."
L["Copy your character into the plan"] = "Euren Charakter in den Plan kopieren"
L["Reads the talents you really have, so you can plan the rest from here. Undo brings the old plan back."] = "Liest die Talente, die Ihr wirklich habt, damit Ihr den Rest von hier aus planen könnt. Rückgängig bringt den alten Plan zurück."
L["Share this build"] = "Diese Skillung teilen"
L["Opens the Builds page with this plan's link selected, ready for Ctrl+C. The same link the site makes."] = "Öffnet die Seite Skillungen mit dem Link dieses Plans markiert, bereit für Strg+C. Derselbe Link, den die Website erzeugt."
L["Load a build"] = "Eine Skillung laden"
L["Opens the Builds page with the paste box ready for a talentsforever.com link or code."] = "Öffnet die Seite Skillungen mit dem Einfügefeld bereit für einen Link oder Code von talentsforever.com."
